export function applyPosterFix3(list) {
  return list.map((m) => {
    const fix = POSTER_FIX3[m.title];
    if (!fix) return m;
    const out = { ...m };
    if (!out.poster || out.poster.includes('placehold.co')) out.poster = fix[0];
    if (!out.backdrop || out.backdrop.includes('placehold.co')) out.backdrop = fix[1];
    return out;
  });
}
